content:
/**
 * Daily Companion — 主应用逻辑
 * 全天候主动陪伴 · 晨间知识 · 待办追踪 · 晚间复盘
 */

// 音效系统兜底（防止 sound.js 加载失败导致崩溃）
if (typeof SoundSystem === 'undefined') {
  window.SoundSystem = {
    enabled: false,
    init() {}, resume() {}, toggle() { return false; },
    playChime() {}, playMessage() {}, playSend() {},
    playSuccess() {}, playCheck() {}, playOpen() {},
    playClose() {}, playError() {}, playAmbient() {}
  };
}

const App = {
  // ========== 状态 ==========
  state: {
    currentFlow: null,     // 当前对话流程: morning | todo | evening | idle
    flowStep: 0,           // 流程中的步骤
    todayTodos: [],        // 今日待办
    history: [],           // 聊天记录
    knowledgeLearned: [],  // 今日已学知识
    growthNotes: [],       // 成长记录
    morningDone: false,
    todoDone: false,
    eveningDone: false,
    lastDate: null,
  },

  // ========== 初始化 ==========
  init() {
    this.loadState();
    this.checkNewDay();
    this.initUI();
    this.initEvents();
    this.startScheduler();
    this.updateLiveTime();
    setInterval(() => this.updateLiveTime(), 1000);

    // 首次音效初始化（需用户交互后）
    const initSound = () => {
      SoundSystem.init();
      SoundSystem.resume();
    };
    document.addEventListener('click', initSound, { once: true });
    document.addEventListener('keydown', initSound, { once: true });

    // 延迟欢迎
    setTimeout(() => {
      this.showWelcomeBack();
    }, 800);
  },

  // ========== 数据持久化 ==========
  loadState() {
    const saved = localStorage.getItem('dc_state');
    if (saved) {
      const data = JSON.parse(saved);
      this.state = { ...this.state, ...data };
    }
  },

  saveState() {
    localStorage.setItem('dc_state', JSON.stringify(this.state));
  },

  checkNewDay() {
    const today = new Date().toISOString().split('T')[0];
    if (this.state.lastDate !== today) {
      // 新的一天，重置当日状态
      this.state.lastDate = today;
      this.state.morningDone = false;
      this.state.todoDone = false;
      this.state.eveningDone = false;
      this.state.knowledgeLearned = [];
      this.state.growthNotes = [];
      // 待办保留，但标记为昨日
      this.state.todayTodos = this.state.todayTodos || [];
      this.saveState();
    }
  },

  // ========== UI 初始化 ==========
  initUI() {
    // 音效开关
    const soundBtn = document.getElementById('soundToggle');
    if (typeof SoundSystem !== 'undefined') {
      if (!SoundSystem.enabled) soundBtn.classList.remove('active');
      else soundBtn.classList.add('active');
    }

    // 渲染待办
    this.renderTodos();

    // 更新时间轴状态
    this.updateTimeline();
  },

  initEvents() {
    // 发送消息
    const input = document.getElementById('chatInput');
    const sendBtn = document.getElementById('btnSend');

    sendBtn.addEventListener('click', () => this.handleUserInput());
    input.addEventListener('keydown', (e) => {
      if (e.key === 'Enter') this.handleUserInput();
    });

    // 音效开关
    document.getElementById('soundToggle').addEventListener('click', (e) => {
      const on = SoundSystem.toggle();
      e.currentTarget.classList.toggle('active', on);
      this.showToast(on ? '🔔 音效已开启' : '🔕 音效已关闭');
    });

    // 主题切换
    document.getElementById('themeToggle').addEventListener('click', () => {
      const isDark = document.documentElement.getAttribute('data-theme') === 'dark';
      document.documentElement.setAttribute('data-theme', isDark ? 'light' : 'dark');
      localStorage.setItem('dc_theme', isDark ? 'light' : 'dark');
    });
    const savedTheme = localStorage.getItem('dc_theme');
    if (savedTheme) document.documentElement.setAttribute('data-theme', savedTheme);

    // 待办弹窗
    document.getElementById('btnAddTodo').addEventListener('click', () => this.openTodoModal());
    document.getElementById('btnCloseTodo').addEventListener('click', () => this.closeTodoModal());
    document.getElementById('btnCancelTodo').addEventListener('click', () => this.closeTodoModal());
    document.getElementById('btnConfirmTodo').addEventListener('click', () => this.confirmAddTodo());

    // 优先级选择
    document.querySelectorAll('.priority-btn').forEach(btn => {
      btn.addEventListener('click', () => {
        document.querySelectorAll('.priority-btn').forEach(b => b.classList.remove('active'));
        btn.classList.add('active');
      });
    });

    // 复盘弹窗
    document.getElementById('btnReview').addEventListener('click', () => this.openReviewModal());
    document.getElementById('btnCloseReview').addEventListener('click', () => this.closeReviewModal());

    // 复盘标签页
    document.querySelectorAll('.review-tab').forEach(tab => {
      tab.addEventListener('click', () => {
        document.querySelectorAll('.review-tab').forEach(t => t.classList.remove('active'));
        tab.classList.add('active');
        this.renderReviewContent(tab.dataset.tab);
      });
    });

    // 移动端侧边栏切换
    const btnMenu = document.getElementById('btnMenu');
    const sidePanel = document.getElementById('sidePanel');
    const sidePanelOverlay = document.getElementById('sidePanelOverlay');
    if (btnMenu && sidePanel && sidePanelOverlay) {
      btnMenu.addEventListener('click', () => {
        sidePanel.classList.toggle('open');
        sidePanelOverlay.classList.toggle('show');
      });
      sidePanelOverlay.addEventListener('click', () => {
        sidePanel.classList.remove('open');
        sidePanelOverlay.classList.remove('show');
      });
    }

    // 点击遮罩关闭弹窗
    document.getElementById('todoModal').addEventListener('click', (e) => {
      if (e.target === e.currentTarget) this.closeTodoModal();
    });
    document.getElementById('reviewModal').addEventListener('click', (e) => {
      if (e.target === e.currentTarget) this.closeReviewModal();
    });
  },

  // ========== 定时调度器 ==========
  startScheduler() {
    // 每分钟检查一次
    setInterval(() => this.checkSchedule(), 60000);
    // 启动时立即检查
    this.checkSchedule();
  },

  checkSchedule() {
    const now = new Date();
    const hour = now.getHours();
    const minute = now.getMinutes();

    // 09:00 晨间知识
    if (hour === 9 && minute === 0 && !this.state.morningDone) {
      this.triggerMorningFlow();
    }

    // 18:00 晚间复盘
    if (hour === 18 && minute === 0 && !this.state.eveningDone) {
      this.triggerEveningFlow();
    }

    this.updateTimeline();
  },

  updateTimeline() {
    const hour = new Date().getHours();

    // 更新时间点状态
    const setStatus = (id, done, active) => {
      const el = document.getElementById(id);
      const dot = document.getElementById(id.replace('status', 'dot'));
      if (!el || !dot) return;
      el.textContent = done ? '已完成' : active ? '进行中' : '待开始';
      el.classList.toggle('done', done);
      dot.classList.toggle('done', done);
      dot.classList.toggle('active', active && !done);
    };

    setStatus('status9', this.state.morningDone, hour >= 9 && hour < 12);
    setStatus('status9sub', this.state.todoDone, this.state.currentFlow === 'todo');
    setStatus('status18', this.state.eveningDone, hour >= 18);
  },

  updateLiveTime() {
    try {
      const now = new Date();
      const timeStr = now.toLocaleTimeString('zh-CN', { hour: '2-digit', minute: '2-digit' });
      const liveTimeEl = document.getElementById('liveTime');
      const currentTimeEl = document.getElementById('currentTime');
      if (liveTimeEl) liveTimeEl.textContent = timeStr;
      if (currentTimeEl) currentTimeEl.textContent = timeStr;
    } catch (e) {
      // 静默处理，避免定时器崩溃
    }
  },

  // ========== 欢迎回来 ==========
  showWelcomeBack() {
    const hour = new Date().getHours();
    let greeting = '你好呀';
    if (hour < 12) greeting = '早上好';
    else if (hour < 18) greeting = '下午好';
    else greeting = '晚上好';

    const messages = [
      `${greeting}！我是 <strong>小咪</strong>，你的全天候陪伴助手 ✨`,
      `我会每天准时陪你聊天、推送知识、记录待办、晚间复盘。`,
      `现在时间是 <strong>${new Date().toLocaleTimeString('zh-CN', { hour: '2-digit', minute: '2-digit' })}</strong>，让我们一起度过美好的一天吧～`
    ];

    // 检查今日进度
    const doneCount = [this.state.morningDone, this.state.todoDone, this.state.eveningDone].filter(Boolean).length;
    if (doneCount > 0) {
      messages.push(`今日已完成 <strong>${doneCount}/3</strong> 个陪伴任务，继续加油！`);
    }

    this.sendAIMessage(messages.join('<br>'), { delay: 500 });
    SoundSystem.playAmbient();
  },

  // ========== 晨间流程 ==========
  triggerMorningFlow() {
    this.state.currentFlow = 'morning';
    this.state.flowStep = 0;
    this.state.morningDone = true;
    this.saveState();

    const knowledge = KnowledgeDB.getAllToday();
    this.state.knowledgeLearned = Object.values(knowledge);
    this.saveState();

    // 主动发起对话
    setTimeout(() => {
      this.sendAIMessage('🌅 早上好！新的一天开始了，小咪来陪你开启晨间学习时光～');
      SoundSystem.playMessage();
    }, 500);

    setTimeout(() => {
      this.sendAIMessage('今天为你准备了四个领域的知识卡片，我们一起来看看吧！');
    }, 2000);

    // 依次展示四类知识
    const categories = [
      { key: 'word', label: '英文单词', emoji: '📖' },
      { key: 'tech', label: '前沿科技', emoji: '🚀' },
      { key: 'history', label: '历史知识', emoji: '🏛️' },
      { key: 'movie', label: '影视动画', emoji: '🎬' }
    ];

    let delay = 3500;
    categories.forEach((cat, i) => {
      setTimeout(() => {
        this.showKnowledgeCard(knowledge[cat.key]);
        SoundSystem.playChime(600 + i * 100);
      }, delay);
      delay += 3500;
    });

    // 知识展示完毕后，进入待办登记
    setTimeout(() => {
      this.sendAIMessage('晨间知识推送完毕！你对哪一条最感兴趣呢？可以随时和我聊聊～');
      this.setQuickReplies(['学到了！', '很有趣', '继续吧']);
    }, delay + 1000);

    // 延迟后询问待办
    setTimeout(() => {
      this.triggerTodoFlow();
    }, delay + 5000);
  },

  showKnowledgeCard(item) {
    const tags = { words: 'word', tech: 'tech', history: 'history', movies: 'movie' };
    const emojis = { words: '📖', tech: '🚀', history: '🏛️', movies: '🎬' };
    const tag = tags[item.category] || item.category;
    const emoji = emojis[item.category] || '✨';

    let html = `<div class="knowledge-card">`;
    html += `<span class="card-tag ${tag}">${emoji} ${this.getCategoryName(item.category)}</span>`;

    if (item.word) {
      html += `<h4>${item.word}</h4>`;
      html += `<div class="phonetic">${item.phonetic}</div>`;
      html += `<div class="meaning">${item.meaning}</div>`;
      html += `<div class="example">${item.example}</div>`;
    } else if (item.title) {
      html += `<h4>${item.title}</h4>`;
      html += `<div class="meaning">${item.content}</div>`;
      if (item.quote) html += `<div class="quote">${item.quote}</div>`;
      if (item.source) html += `<div class="source">来源：${item.source}</div>`;
      if (item.era) html += `<div class="era">年代：${item.era}</div>`;
    }

    html += `</div>`;

    this.sendAIMessage(html, { isHTML: true });
  },

  getCategoryName(cat) {
    const names = { words: '英文单词', tech: '前沿科技', history: '历史知识', movies: '影视动画' };
    return names[cat] || cat;
  },

  // ========== 待办流程 ==========
  triggerTodoFlow() {
    this.state.currentFlow = 'todo';
    this.state.flowStep = 0;
    this.saveState();

    this.sendAIMessage('📋 接下来，我们来记录一下今天的重要待办事项吧！');
    setTimeout(() => {
      this.sendAIMessage('你今天有什么重要的事情需要完成吗？可以告诉我，我会帮你记下来。');
      this.setQuickReplies(['没有特别的', '有，我来说说', '稍后再记']);
    }, 1500);
  },

  handleTodoInput(text) {
    if (text.includes('没有') || text.includes('暂无') || text.includes('没')) {
      this.sendAIMessage('好的，那今天就轻松度过吧～如果想到什么待办，随时可以在侧边栏添加哦！');
      this.state.todoDone = true;
      this.state.currentFlow = 'idle';
      this.saveState();
      this.setQuickReplies([]);
      return;
    }

    if (text.includes('稍后') || text.includes('等会')) {
      this.sendAIMessage('没问题，待办登记随时可以进行。侧边栏有「添加待办」按钮，想记的时候点一下就好～');
      this.state.currentFlow = 'idle';
      this.saveState();
      this.setQuickReplies([]);
      return;
    }

    // 解析待办
    const todos = text.split(/[,，;；、]/).map(t => t.trim()).filter(t => t.length > 0);
    if (todos.length === 0) {
      this.sendAIMessage('我好像没听清楚，可以再说一遍你的待办事项吗？');
      return;
    }

    todos.forEach(todo => {
      this.addTodo(todo, 'normal');
    });

    this.sendAIMessage(`已记录 <strong>${todos.length}</strong> 条待办事项！你可以在左侧面板查看和管理。`);
    SoundSystem.playSuccess();

    // 提示下半年复盘
    const now = new Date();
    if (now.getMonth() >= 6) { // 下半年
      this.sendAIMessage('📅 对了，现在是下半年了，我会定期帮你回顾待办的完成情况，确保重要事项不遗漏。');
    }

    this.state.todoDone = true;
    this.state.currentFlow = 'idle';
    this.saveState();
    this.setQuickReplies(['谢谢小咪！', '查看待办']);
  },

  // ========== 晚间复盘流程 ==========
  triggerEveningFlow() {
    this.state.currentFlow = 'evening';
    this.state.flowStep = 0;
    this.state.eveningDone = true;
    this.saveState();

    const hour = new Date().getHours();
    const greeting = hour >= 18 ? '晚上好' : '下午好';

    setTimeout(() => {
      this.sendAIMessage(`🌙 ${greeting}！忙碌的一天即将结束，是时候做个小小的复盘了。`);
      SoundSystem.playMessage();
    }, 500);

    setTimeout(() => {
      this.sendAIMessage('今天有什么让你感到开心或有所收获的事情吗？可以和我分享一下～');
      this.setQuickReplies(['学到了新知识', '完成了目标', '度过了平静的一天']);
    }, 2500);
  },

  handleEveningInput(text) {
    // 记录成长
    this.state.growthNotes.push({
      text: text,
      time: new Date().toISOString()
    });
    this.saveState();

    if (this.state.flowStep === 0) {
      this.state.flowStep = 1;
      this.saveState();

      this.sendAIMessage('很棒！记录成长是自我提升的重要一步 ✨');
      setTimeout(() => {
        // 回顾今日知识
        if (this.state.knowledgeLearned.length > 0) {
          const randomKnowledge = this.state.knowledgeLearned[Math.floor(Math.random() * this.state.knowledgeLearned.length)];
          this.sendAIMessage('来做个知识巩固吧！还记得今天学的这条内容吗？');
          this.showKnowledgeCard(randomKnowledge);
        }
      }, 1500);

      setTimeout(() => {
        this.sendAIMessage('今天的陪伴就到这里啦。好好休息，明天见！🌟');
        this.setQuickReplies(['明天见！', '晚安小咪']);
      }, 5000);
    } else {
      this.sendAIMessage('晚安！愿你有个好梦，明天我们继续一起进步～ 🌙');
      this.state.currentFlow = 'idle';
      this.saveState();
      this.setQuickReplies([]);
    }
  },

  // ========== 用户输入处理 ==========
  handleUserInput() {
    const input = document.getElementById('chatInput');
    const text = input.value.trim();
    if (!text) return;

    input.value = '';
    this.sendUserMessage(text);
    SoundSystem.playSend();

    // 根据当前流程处理
    if (this.state.currentFlow === 'todo') {
      this.handleTodoInput(text);
    } else if (this.state.currentFlow === 'evening') {
      this.handleEveningInput(text);
    } else {
      this.handleFreeChat(text);
    }
  },

  handleFreeChat(text) {
    // ===== 语义意图识别（按优先级排序）=====

    // 1. 天气查询
    if (/天气|气温|温度|下雨|下雪|雾霾|空气质量/.test(text)) {
      this.sendAIMessage('☁️ 抱歉，我目前还没有接入实时天气数据，没法帮你查天气～推荐用系统天气 App 或搜索引擎查看哦！');
      return;
    }

    // 2. 时间/日期查询
    if (/几点|现在时间|今天几号|星期几|日期/.test(text)) {
      const now = new Date();
      const timeStr = now.toLocaleTimeString('zh-CN', { hour: '2-digit', minute: '2-digit' });
      const dateStr = now.toLocaleDateString('zh-CN', { month: 'long', day: 'numeric', weekday: 'long' });
      this.sendAIMessage(`🕐 现在是 <strong>${timeStr}</strong>，${dateStr}。`);
      return;
    }

    // 3. 问候/打招呼
    if (/^(你好|您好|嗨|hello|hi|在吗|在嘛)\s*[.!?！？]*$/i.test(text)) {
      this.sendAIMessage('你好呀！我是小咪，有什么我可以帮你的吗？😊');
      return;
    }

    // 4. 询问能力/身份
    if (/你能做什么|你是谁|你有什么功能|你会什么/.test(text)) {
      this.sendAIMessage('我是 <strong>小咪</strong>，你的全天候陪伴助手！我可以：<br>📖 每天推送知识卡片（单词、科技、历史、影视）<br>📝 帮你记录和管理待办事项<br>🌙 晚间陪你复盘成长<br>💬 随时陪你聊天<br><br>试试输入「知识」或「待办」体验一下吧～');
      return;
    }

    // 5. 表达感谢
    if (/谢谢|感谢|多谢/.test(text)) {
      this.sendAIMessage('不客气呀！能帮到你我很开心～随时找我 ✨');
      return;
    }

    // 6. 表达负面情绪
    if (/难过|伤心|累|烦|不开心|郁闷|焦虑/.test(text)) {
      this.sendAIMessage('抱抱你 🤗 每个人都有低落的时候，允许自己休息一会儿。如果想聊聊，我随时在听；如果想转移注意力，我可以给你推送一条有趣的知识～');
      this.setQuickReplies(['推送知识', '我想静静', '谢谢小咪']);
      return;
    }

    // ===== 关键词回应（原有功能）=====
    if (text.includes('知识') || text.includes('学习')) {
      this.sendAIMessage('想学习的话，我可以随时为你推送知识卡片！想学什么类型的？');
      this.setQuickReplies(['英文单词', '科技资讯', '历史知识', '影视动画']);
      return;
    }
    if (text.includes('待办') || text.includes('todo')) {
      this.sendAIMessage('待办事项在左侧面板可以看到，也可以直接在这里告诉我新的待办哦！');
      return;
    }
    if (text.includes('复盘') || text.includes('总结')) {
      this.sendAIMessage('复盘记录可以在右上角 📋 按钮查看。需要我现在帮你总结一下吗？');
      return;
    }
    if (text.includes('单词') || text.includes('英语')) {
      const word = KnowledgeDB.getToday('words');
      this.showKnowledgeCard(word);
      return;
    }
    if (text.includes('科技')) {
      const tech = KnowledgeDB.getToday('tech');
      this.showKnowledgeCard(tech);
      return;
    }
    if (text.includes('历史')) {
      const history = KnowledgeDB.getToday('history');
      this.showKnowledgeCard(history);
      return;
    }
    if (text.includes('电影') || text.includes('动画')) {
      const movie = KnowledgeDB.getToday('movies');
      this.showKnowledgeCard(movie);
      return;
    }

    // ===== 兜底回复（不再随机乱答）=====
    this.sendAIMessage('我在听呢 👂 不过这个问题我暂时还没学会怎么回答～你可以试试问我「天气」「时间」「知识」「待办」相关的内容，或者点击下方的快捷回复按钮。');
  },

  // ========== 消息系统 ==========
  sendAIMessage(content, options = {}) {
    const container = document.getElementById('chatMessages');
    const msgDiv = document.createElement('div');
    msgDiv.className = 'message ai';
    msgDiv.style.animationDelay = `${options.delay || 0}ms`;

    const bubble = document.createElement('div');
    bubble.className = 'message-bubble glass';

    if (options.isHTML) {
      bubble.innerHTML = content;
    } else {
      // 打字机效果
      bubble.innerHTML = '<span class="typing-indicator"><span></span><span></span><span></span></span>';
      msgDiv.appendChild(bubble);
      container.appendChild(msgDiv);
      this.scrollToBottom();

      setTimeout(() => {
        bubble.innerHTML = content;
        SoundSystem.playMessage();
      }, 800 + (options.delay || 0));
      return;
    }

    msgDiv.appendChild(bubble);
    container.appendChild(msgDiv);
    this.scrollToBottom();
  },

  sendUserMessage(content) {
    const container = document.getElementById('chatMessages');
    const msgDiv = document.createElement('div');
    msgDiv.className = 'message user';

    const bubble = document.createElement('div');
    bubble.className = 'message-bubble';
    bubble.textContent = content;

    msgDiv.appendChild(bubble);
    container.appendChild(msgDiv);
    this.scrollToBottom();

    // 保存记录
    this.state.history.push({ role: 'user', text: content, time: new Date().toISOString() });
    this.saveState();
  },

  scrollToBottom() {
    const container = document.getElementById('chatMessages');
    setTimeout(() => {
      container.scrollTop = container.scrollHeight;
    }, 50);
  },

  setQuickReplies(replies) {
    const container = document.getElementById('quickReplies');
    container.innerHTML = '';
    replies.forEach(text => {
      const btn = document.createElement('button');
      btn.className = 'quick-reply';
      btn.textContent = text;
      btn.addEventListener('click', () => {
        document.getElementById('chatInput').value = text;
        this.handleUserInput();
      });
      container.appendChild(btn);
    });
  },

  // ========== 待办系统 ==========
  addTodo(text, priority = 'normal') {
    const todo = {
      id: Date.now() + Math.random(),
      text,
      priority,
      done: false,
      createdAt: new Date().toISOString()
    };
    this.state.todayTodos.push(todo);
    this.saveState();
    this.renderTodos();
  },

  toggleTodo(id) {
    const todo = this.state.todayTodos.find(t => t.id === id);
    if (todo) {
      todo.done = !todo.done;
      this.saveState();
      this.renderTodos();
      if (todo.done) SoundSystem.playCheck();
    }
  },

  deleteTodo(id) {
    this.state.todayTodos = this.state.todayTodos.filter(t => t.id !== id);
    this.saveState();
    this.renderTodos();
  },

  renderTodos() {
    const list = document.getElementById('todoList');
    const count = document.getElementById('todoCount');

    count.textContent = this.state.todayTodos.filter(t => !t.done).length;

    if (this.state.todayTodos.length === 0) {
      list.innerHTML = '<div class="empty-state">暂无待办事项</div>';
      return;
    }

    list.innerHTML = '';
    this.state.todayTodos.forEach(todo => {
      const item = document.createElement('div');
      item.className = `todo-item ${todo.done ? 'done' : ''}`;
      item.innerHTML = `
        <div class="todo-check">
          <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="3">
            <polyline points="20 6 9 17 4 12"></polyline>
          </svg>
        </div>
        <span class="todo-text">${this.escapeHtml(todo.text)}</span>
        <span class="todo-priority ${todo.priority}"></span>
      `;
      item.addEventListener('click', () => this.toggleTodo(todo.id));
      list.appendChild(item);
    });
  },

  openTodoModal() {
    document.getElementById('todoModal').classList.add('show');
    document.getElementById('todoInput').value = '';
    document.getElementById('todoInput').focus();
    SoundSystem.playOpen();
  },

  closeTodoModal() {
    document.getElementById('todoModal').classList.remove('show');
    SoundSystem.playClose();
  },

  confirmAddTodo() {
    const input = document.getElementById('todoInput');
    const text = input.value.trim();
    if (!text) return;

    const priorityBtn = document.querySelector('.priority-btn.active');
    const priority = priorityBtn ? priorityBtn.dataset.p : 'normal';

    this.addTodo(text, priority);
    this.closeTodoModal();
    this.showToast('✅ 待办已添加');
    SoundSystem.playSuccess();
  },

  // ========== 复盘系统 ==========
  openReviewModal() {
    document.getElementById('reviewModal').classList.add('show');
    this.renderReviewContent('today');
    SoundSystem.playOpen();
  },

  closeReviewModal() {
    document.getElementById('reviewModal').classList.remove('show');
    SoundSystem.playClose();
  },

  renderReviewContent(tab) {
    const container = document.getElementById('reviewContent');
    container.innerHTML = '';

    if (tab === 'today') {
      // 今日数据
      const today = new Date().toISOString().split('T')[0];
      const todayTodos = this.state.todayTodos;
      const doneCount = todayTodos.filter(t => t.done).length;
      const growthCount = this.state.growthNotes.length;

      let html = '<div class="review-item">';
      html += `<div class="review-date">📅 ${today}</div>`;
      html += `<div class="review-text">`;
      html += `今日待办：${doneCount}/${todayTodos.length} 项完成<br>`;
      html += `成长记录：${growthCount} 条<br>`;
      html += `知识学习：${this.state.knowledgeLearned.length} 条`;
      html += `</div></div>`;

      if (this.state.growthNotes.length > 0) {
        this.state.growthNotes.forEach(note => {
          html += '<div class="review-item">';
          html += `<div class="review-date">🌱 ${new Date(note.time).toLocaleTimeString('zh-CN', { hour: '2-digit', minute: '2-digit' })}</div>`;
          html += `<div class="review-text">${this.escapeHtml(note.text)}</div>`;
          html += '</div>';
        });
      }

      container.innerHTML = html;
    } else if (tab === 'week') {
      container.innerHTML = '<div class="empty-state">本周回顾功能开发中，敬请期待 ✨</div>';
    } else {
      container.innerHTML = '<div class="empty-state">历史记录功能开发中，敬请期待 ✨</div>';
    }
  },

  // ========== 工具方法 ==========
  showToast(message) {
    const container = document.getElementById('toastContainer');
    const toast = document.createElement('div');
    toast.className = 'toast';
    toast.innerHTML = `<span class="toast-icon">✨</span><span>${message}</span>`;
    container.appendChild(toast);
    setTimeout(() => toast.remove(), 3500);
  },

  escapeHtml(text) {
    const div = document.createElement('div');
    div.textContent = text;
    return div.innerHTML;
  }
};

// 启动应用
document.addEventListener('DOMContentLoaded', () => App.init());

/* ============================================
   Daily Companion — 全局样式
   清新柔和 · 磨砂玻璃 · 渐变 · 动态交互
   ============================================ */

:root {
  /* 主色调 — 柔和渐变系 */
  --c-primary: #7C6BFF;
  --c-primary-light: #A89BFF;
  --c-secondary: #FF8A8A;
  --c-accent: #5DD3C5;
  --c-warm: #FFD166;
  --c-rose: #F4A4C0;

  /* 背景渐变 */
  --bg-gradient-1: linear-gradient(135deg, #f5f0ff 0%, #fff0f3 30%, #f0f9ff 60%, #f5fff8 100%);
  --bg-gradient-dark: linear-gradient(135deg, #1a1625 0%, #251a20 30%, #1a2028 60%, #1a251f 100%);

  /* 玻璃态 */
  --glass-bg: rgba(255, 255, 255, 0.55);
  --glass-bg-dark: rgba(30, 30, 45, 0.6);
  --glass-border: rgba(255, 255, 255, 0.4);
  --glass-border-dark: rgba(255, 255, 255, 0.08);
  --glass-shadow: 0 8px 32px rgba(124, 107, 255, 0.12), 0 2px 8px rgba(0, 0, 0, 0.04);
  --glass-shadow-dark: 0 8px 32px rgba(0, 0, 0, 0.3), 0 2px 8px rgba(0, 0, 0, 0.2);

  /* 文字 */
  --text-primary: #2d2a3e;
  --text-secondary: #6b6880;
  --text-muted: #a09eb5;
  --text-primary-dark: #e8e6f0;
  --text-secondary-dark: #b0acc8;

  /* 间距 */
  --radius-sm: 12px;
  --radius-md: 18px;
  --radius-lg: 24px;
  --radius-xl: 32px;

  /* 动画 */
  --ease-out: cubic-bezier(0.16, 1, 0.3, 1);
  --ease-spring: cubic-bezier(0.34, 1.56, 0.64, 1);
}

[data-theme="dark"] {
  --glass-bg: var(--glass-bg-dark);
  --glass-border: var(--glass-border-dark);
  --glass-shadow: var(--glass-shadow-dark);
  --text-primary: var(--text-primary-dark);
  --text-secondary: var(--text-secondary-dark);
}

* {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

html {
  font-size: 15px;
}

body {
  font-family: 'Outfit', 'Noto Sans SC', -apple-system, sans-serif;
  color: var(--text-primary);
  min-height: 100vh;
  overflow: hidden;
  background: var(--bg-gradient-1);
  transition: background 0.6s ease;
}

[data-theme="dark"] body {
  background: var(--bg-gradient-dark);
}

/* ============================================
   动态背景
   ============================================ */
.bg-gradient {
  position: fixed;
  inset: 0;
  z-index: -3;
  background: var(--bg-gradient-1);
  transition: background 0.8s ease;
}

.bg-noise {
  position: fixed;
  inset: 0;
  z-index: -2;
  opacity: 0.03;
  background-image: url("data:image/svg+xml,%3Csvg viewBox='0 0 256 256' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='n'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='0.9' numOctaves='4' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23n)'/%3E%3C/svg%3E");
  background-size: 200px;
  pointer-events: none;
}

.bg-orb {
  position: fixed;
  border-radius: 50%;
  filter: blur(80px);
  opacity: 0.5;
  z-index: -1;
  animation: orbFloat 20s ease-in-out infinite;
}

.orb-1 {
  width: 500px;
  height: 500px;
  background: radial-gradient(circle, rgba(124, 107, 255, 0.25), transparent 70%);
  top: -10%;
  left: -5%;
  animation-delay: 0s;
}

.orb-2 {
  width: 400px;
  height: 400px;
  background: radial-gradient(circle, rgba(244, 164, 192, 0.2), transparent 70%);
  bottom: -10%;
  right: -5%;
  animation-delay: -7s;
}

.orb-3 {
  width: 350px;
  height: 350px;
  background: radial-gradient(circle, rgba(93, 211, 197, 0.18), transparent 70%);
  top: 40%;
  left: 50%;
  animation-delay: -14s;
}

@keyframes orbFloat {
  0%, 100% { transform: translate(0, 0) scale(1); }
  25% { transform: translate(30px, -20px) scale(1.05); }
  50% { transform: translate(-20px, 30px) scale(0.95); }
  75% { transform: translate(20px, 20px) scale(1.02); }
}

/* ============================================
   磨砂玻璃组件
   ============================================ */
.glass {
  background: var(--glass-bg);
  backdrop-filter: blur(24px) saturate(1.4);
  -webkit-backdrop-filter: blur(24px) saturate(1.4);
  border: 1px solid var(--glass-border);
  box-shadow: var(--glass-shadow);
}

/* ============================================
   顶部栏
   ============================================ */
.top-bar {
  position: fixed;
  top: 16px;
  left: 16px;
  right: 16px;
  height: 56px;
  border-radius: var(--radius-lg);
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 0 20px;
  z-index: 100;
}

.logo {
  display: flex;
  align-items: center;
  gap: 10px;
}

.logo-icon {
  font-size: 22px;
  animation: iconPulse 3s ease-in-out infinite;
}

@keyframes iconPulse {
  0%, 100% { transform: scale(1) rotate(0deg); opacity: 0.9; }
  50% { transform: scale(1.15) rotate(10deg); opacity: 1; }
}

.logo-text {
  font-size: 1.1rem;
  font-weight: 600;
  letter-spacing: -0.3px;
  background: linear-gradient(135deg, var(--c-primary), var(--c-rose));
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  background-clip: text;
}

.top-actions {
  display: flex;
  gap: 8px;
}

.icon-btn {
  width: 36px;
  height: 36px;
  border-radius: 50%;
  border: none;
  background: rgba(255, 255, 255, 0.3);
  color: var(--text-secondary);
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  transition: all 0.3s var(--ease-out);
}

.icon-btn:hover {
  background: rgba(124, 107, 255, 0.15);
  color: var(--c-primary);
  transform: translateY(-2px);
}

.icon-btn.active {
  background: rgba(124, 107, 255, 0.2);
  color: var(--c-primary);
}

/* ============================================
   主容器
   ============================================ */
.main-container {
  display: flex;
  gap: 16px;
  padding: 88px 16px 16px;
  height: 100vh;
}

/* ============================================
   侧边面板
   ============================================ */
.side-panel {
  width: 280px;
  min-width: 280px;
  border-radius: var(--radius-lg);
  padding: 20px;
  display: flex;
  flex-direction: column;
  overflow: hidden;
  transition: transform 0.4s var(--ease-out);
}

.panel-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 16px;
}

.panel-header h3 {
  font-size: 0.95rem;
  font-weight: 600;
  color: var(--text-primary);
}

.live-time {
  font-size: 0.8rem;
  font-weight: 500;
  color: var(--c-primary);
  font-variant-numeric: tabular-nums;
}

.badge {
  background: linear-gradient(135deg, var(--c-primary), var(--c-rose));
  color: white;
  font-size: 0.7rem;
  font-weight: 600;
  padding: 2px 8px;
  border-radius: 10px;
}

/* 时间轴 */
.timeline {
  display: flex;
  flex-direction: column;
  gap: 0;
  margin-bottom: 20px;
}

.timeline-item {
  display: flex;
  align-items: flex-start;
  gap: 12px;
  padding: 10px 0;
  position: relative;
}

.timeline-item[data-sub] {
  padding-left: 16px;
  opacity: 0.85;
}

.timeline-item:not(:last-child)::after {
  content: '';
  position: absolute;
  left: 7px;
  top: 28px;
  width: 2px;
  height: calc(100% - 8px);
  background: linear-gradient(to bottom, var(--c-primary-light), transparent);
  opacity: 0.3;
}

.timeline-dot {
  width: 16px;
  height: 16px;
  border-radius: 50%;
  background: linear-gradient(135deg, var(--c-primary-light), var(--c-primary));
  border: 3px solid rgba(255, 255, 255, 0.6);
  box-shadow: 0 0 12px rgba(124, 107, 255, 0.3);
  flex-shrink: 0;
  margin-top: 2px;
  transition: all 0.4s var(--ease-spring);
}

.timeline-dot.small {
  width: 12px;
  height: 12px;
  margin-left: 2px;
}

.timeline-dot.done {
  background: linear-gradient(135deg, var(--c-accent), #3cbba8);
  box-shadow: 0 0 12px rgba(93, 211, 197, 0.4);
}

.timeline-dot.active {
  animation: dotPulse 2s ease-in-out infinite;
}

@keyframes dotPulse {
  0%, 100% { box-shadow: 0 0 12px rgba(124, 107, 255, 0.3); }
  50% { box-shadow: 0 0 20px rgba(124, 107, 255, 0.6); }
}

.timeline-content {
  display: flex;
  flex-direction: column;
  gap: 2px;
  flex: 1;
}

.time-label {
  font-size: 0.75rem;
  font-weight: 500;
  color: var(--c-primary);
}

.task-label {
  font-size: 0.85rem;
  font-weight: 500;
  color: var(--text-primary);
}

.status {
  font-size: 0.7rem;
  color: var(--text-muted);
}

.status.done {
  color: var(--c-accent);
}

.panel-divider {
  height: 1px;
  background: linear-gradient(to right, transparent, var(--glass-border), transparent);
  margin: 8px 0 16px;
}

/* 待办列表 */
.todo-list {
  flex: 1;
  overflow-y: auto;
  display: flex;
  flex-direction: column;
  gap: 8px;
  margin-bottom: 12px;
}

.todo-list::-webkit-scrollbar {
  width: 4px;
}

.todo-list::-webkit-scrollbar-thumb {
  background: rgba(124, 107, 255, 0.2);
  border-radius: 4px;
}

.empty-state {
  text-align: center;
  padding: 24px 0;
  color: var(--text-muted);
  font-size: 0.8rem;
}

.todo-item {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 10px 12px;
  background: rgba(255, 255, 255, 0.4);
  border-radius: var(--radius-sm);
  border: 1px solid rgba(255, 255, 255, 0.3);
  transition: all 0.3s var(--ease-out);
  cursor: pointer;
}

.todo-item:hover {
  background: rgba(255, 255, 255, 0.6);
  transform: translateX(4px);
}

.todo-item.done {
  opacity: 0.5;
}

.todo-item.done .todo-text {
  text-decoration: line-through;
  color: var(--text-muted);
}

.todo-check {
  width: 18px;
  height: 18px;
  border-radius: 50%;
  border: 2px solid var(--c-primary-light);
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  transition: all 0.3s var(--ease-spring);
}

.todo-item.done .todo-check {
  background: var(--c-accent);
  border-color: var(--c-accent);
}

.todo-check svg {
  width: 10px;
  height: 10px;
  color: white;
  opacity: 0;
  transform: scale(0);
  transition: all 0.3s var(--ease-spring);
}

.todo-item.done .todo-check svg {
  opacity: 1;
  transform: scale(1);
}

.todo-text {
  font-size: 0.82rem;
  color: var(--text-primary);
  flex: 1;
  line-height: 1.4;
}

.todo-priority {
  width: 6px;
  height: 6px;
  border-radius: 50%;
  flex-shrink: 0;
}

.todo-priority.important { background: var(--c-warm); }
.todo-priority.urgent { background: var(--c-secondary); }
.todo-priority.normal { background: var(--c-accent); }

.btn-add-todo {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  width: 100%;
  padding: 10px;
  border: 1.5px dashed rgba(124, 107, 255, 0.3);
  border-radius: var(--radius-sm);
  background: transparent;
  color: var(--c-primary);
  font-size: 0.82rem;
  font-weight: 500;
  cursor: pointer;
  transition: all 0.3s var(--ease-out);
  font-family: inherit;
}

.btn-add-todo:hover {
  background: rgba(124, 107, 255, 0.08);
  border-color: rgba(124, 107, 255, 0.5);
  transform: translateY(-1px);
}

/* ============================================
   聊天区域
   ============================================ */
.chat-area {
  flex: 1;
  display: flex;
  flex-direction: column;
  border-radius: var(--radius-lg);
  overflow: hidden;
}

.chat-header {
  display: flex;
  align-items: center;
  gap: 14px;
  padding: 14px 20px;
  border-bottom: 1px solid var(--glass-border);
}

.companion-avatar {
  position: relative;
  width: 44px;
  height: 44px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 22px;
}

.avatar-ring {
  position: absolute;
  inset: 0;
  border-radius: 50%;
  border: 2px solid transparent;
  background: linear-gradient(135deg, var(--c-primary), var(--c-rose), var(--c-accent)) border-box;
  -webkit-mask: linear-gradient(#fff 0 0) padding-box, linear-gradient(#fff 0 0);
  mask: linear-gradient(#fff 0 0) padding-box, linear-gradient(#fff 0 0);
  -webkit-mask-composite: xor;
  mask-composite: exclude;
  animation: ringRotate 4s linear infinite;
}

@keyframes ringRotate {
  0% { transform: rotate(0deg); }
  100% { transform: rotate(360deg); }
}

.companion-info h2 {
  font-size: 1rem;
  font-weight: 600;
  color: var(--text-primary);
}

.companion-status {
  font-size: 0.75rem;
  color: var(--text-muted);
  display: flex;
  align-items: center;
  gap: 5px;
}

.status-dot {
  width: 7px;
  height: 7px;
  border-radius: 50%;
  background: var(--c-accent);
  box-shadow: 0 0 8px rgba(93, 211, 197, 0.5);
  animation: statusBlink 2s ease-in-out infinite;
}

@keyframes statusBlink {
  0%, 100% { opacity: 1; }
  50% { opacity: 0.5; }
}

.chat-actions {
  margin-left: auto;
}

/* 消息列表 */
.chat-messages {
  flex: 1;
  overflow-y: auto;
  padding: 20px;
  display: flex;
  flex-direction: column;
  gap: 16px;
  scroll-behavior: smooth;
}

.chat-messages::-webkit-scrollbar {
  width: 5px;
}

.chat-messages::-webkit-scrollbar-thumb {
  background: rgba(124, 107, 255, 0.15);
  border-radius: 4px;
}

/* 消息气泡 */
.message {
  display: flex;
  animation: messageIn 0.5s var(--ease-out) forwards;
  opacity: 0;
  transform: translateY(12px);
}

@keyframes messageIn {
  to { opacity: 1; transform: translateY(0); }
}

.message.system {
  justify-content: center;
}

.message.system .message-bubble {
  max-width: 480px;
  text-align: center;
  background: linear-gradient(135deg, rgba(124, 107, 255, 0.1), rgba(244, 164, 192, 0.08));
}

.message.ai {
  justify-content: flex-start;
}

.message.user {
  justify-content: flex-end;
}

.message-bubble {
  max-width: 70%;
  padding: 14px 18px;
  border-radius: var(--radius-md);
  line-height: 1.7;
  font-size: 0.9rem;
}

.message.ai .message-bubble {
  background: rgba(255, 255, 255, 0.65);
  border-bottom-left-radius: 4px;
}

.message.user .message-bubble {
  background: linear-gradient(135deg, var(--c-primary), #9b8bff);
  color: white;
  border-bottom-right-radius: 4px;
}

.message-bubble p {
  margin-bottom: 8px;
}

.message-bubble p:last-child {
  margin-bottom: 0;
}

.message-bubble .hint {
  font-size: 0.8rem;
  opacity: 0.7;
  margin-top: 8px;
}

/* 知识卡片 */
.knowledge-card {
  background: linear-gradient(135deg, rgba(124, 107, 255, 0.08), rgba(93, 211, 197, 0.06));
  border: 1px solid rgba(124, 107, 255, 0.15);
  border-radius: var(--radius-sm);
  padding: 14px;
  margin: 10px 0;
}

.knowledge-card .card-tag {
  display: inline-block;
  font-size: 0.65rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.5px;
  padding: 3px 8px;
  border-radius: 6px;
  margin-bottom: 8px;
}

.knowledge-card .card-tag.word { background: rgba(124, 107, 255, 0.15); color: var(--c-primary); }
.knowledge-card .card-tag.tech { background: rgba(93, 211, 197, 0.15); color: #2a9d8f; }
.knowledge-card .card-tag.history { background: rgba(255, 209, 102, 0.2); color: #e9c46a; }
