/* ============================================
   弹窗
   ============================================ */
.modal-overlay {
  position: fixed;
  inset: 0;
  background: rgba(0, 0, 0, 0.2);
  backdrop-filter: blur(8px);
  display: flex;
  align-items: center;
  justify-content: center;
  z-index: 200;
  opacity: 0;
  pointer-events: none;
  transition: opacity 0.3s ease;
}

.modal-overlay.show {
  opacity: 1;
  pointer-events: all;
}

.modal {
  width: 420px;
  max-width: 90vw;
  max-height: 80vh;
  border-radius: var(--radius-lg);
  padding: 0;
  overflow: hidden;
  transform: scale(0.9) translateY(20px);
  transition: transform 0.4s var(--ease-spring);
}

.modal-overlay.show .modal {
  transform: scale(1) translateY(0);
}

.modal-large {
  width: 600px;
}

.modal-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 18px 20px;
  border-bottom: 1px solid var(--glass-border);
}

.modal-header h3 {
  font-size: 1rem;
  font-weight: 600;
}

.btn-close {
  width: 28px;
  height: 28px;
  border-radius: 50%;
  border: none;
  background: rgba(0, 0, 0, 0.05);
  color: var(--text-secondary);
  font-size: 1.2rem;
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  transition: all 0.2s;
}

.btn-close:hover {
  background: rgba(255, 107, 107, 0.15);
  color: #ff6b6b;
}

.modal-body {
  padding: 20px;
}

.modal-input {
  width: 100%;
  padding: 12px 16px;
  border-radius: var(--radius-sm);
  border: 1.5px solid rgba(124, 107, 255, 0.2);
  background: rgba(255, 255, 255, 0.5);
  font-size: 0.9rem;
  color: var(--text-primary);
  outline: none;
  font-family: inherit;
  transition: all 0.3s;
}

.modal-input:focus {
